    def __init__(self):
        """Initialize the travel booking bot with API configurations and conversation state."""
        self.conversation_state = {}
        self.api_endpoints = {
            'flights': 'https://api.localtravelcoupons.com/flights',
            'hotels': 'https://api.localtravelcoupons.com/hotels'
        }
