        echo "<p class='product-price'>\${$price}</p>";
        if ($productId) {
            echo "<a href='product.php?id={$productId}' class='product-link'>View Details</a>";
        }
        echo "</div>";
        echo "</div>";
    }

    echo "</div>";
    echo "</div>";
}

// Main execution
try {
    // Initialize API client
    $api = new WoopyTeeAPI(WOOPYTEE_API_KEY);

