        this.axiosInstance = axios.create({
            baseURL: this.baseUrl,
            timeout: this.timeout,
            headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json',
                'User-Agent': 'USASEOShops-GoogleMaps-Client/1.0'
            },
            httpsAgent: new https.Agent({
                keepAlive: true,
                keepAliveMsecs: 1000
            })
        });

