                    switch (status) {
                        case 400:
                            return Promise.reject(new Error(`Bad Request: ${message}`));
                        case 401:
                            return Promise.reject(new Error(`Unauthorized: ${message}`));
                        case 403:
                            return Promise.reject(new Error(`Forbidden: ${message}`));
